using System;
using System.Runtime.Serialization;
using Opc.Ua.Types;

namespace Opc.Ua
{
    /// <summary>
    /// A concrete base class used by the autogenerated code.
    /// </summary>
    [DataContract(Name = "EncodeableObject", Namespace = Namespaces.OpcUaXsd)]
    public abstract class EncodeableObject : IEncodeable
    {
        /// <inheritdoc/>
        public abstract ExpandedNodeId TypeId { get; }

        /// <inheritdoc/>
        public abstract ExpandedNodeId BinaryEncodingId { get; }

        /// <inheritdoc/>
        public abstract ExpandedNodeId XmlEncodingId { get; }

        /// <inheritdoc/>
        public virtual void Encode(IEncoder encoder)
        {
        }

        /// <inheritdoc/>
        public virtual void Decode(IDecoder decoder)
        {
        }

        /// <summary>
        /// Checks if the value has changed.
        /// </summary>
        /// <exception cref="NotImplementedException"></exception>
        public virtual bool IsEqual(IEncodeable? encodeable)
        {
            throw new NotImplementedException("Subclass must implement this method.");
        }

        /// <summary>
        /// Applies the data encoding to the value.
        /// </summary>
        public static ServiceResult ApplyDataEncoding(
            IServiceMessageContext context,
            QualifiedName dataEncoding,
            ref Variant value)
        {
            // check if nothing to do.
            if (dataEncoding.IsNull || value.IsNull)
            {
                return ServiceResult.Good;
            }

            // check for supported encoding type.
            if (dataEncoding.NamespaceIndex != 0)
            {
                return StatusCodes.BadDataEncodingUnsupported;
            }

            bool useXml = dataEncoding.Name == BrowseNames.DefaultXml;

            if (!useXml && dataEncoding.Name != BrowseNames.DefaultBinary)
            {
                return StatusCodes.BadDataEncodingInvalid;
            }

            try
            {
                IEncodeable[]? encodeables = null;

                // check for array of extension objects.
                if (value.TryGetValue(out ArrayOf<ExtensionObject> extensions))
                {
                    // convert extension objects to encodeables.
                    encodeables = new IEncodeable[extensions.Count];

                    for (int ii = 0; ii < encodeables.Length; ii++)
                    {
                        if (extensions[ii].IsNull)
                        {
                            encodeables[ii] = null!;
                            continue;
                        }

                        if (!extensions[ii].TryGetValue(out IEncodeable? element))
                        {
                            return StatusCodes.BadTypeMismatch;
                        }

                        encodeables[ii] = element!;
                    }
                }

                // apply data encoding to the array.
                if (encodeables != null)
                {
                    var buffer = new ExtensionObject[encodeables.Length];
                    for (int ii = 0; ii < buffer.Length; ii++)
                    {
                        // null elements are valid and stay null.
                        buffer[ii] = encodeables[ii] == null
                            ? ExtensionObject.Null
                            : Encode(context, encodeables[ii], useXml);
                    }

                    value = buffer.ToArrayOf();
                    return ServiceResult.Good;
                }

                // check for scalar value.
                if (value.TryGetValue(out ExtensionObject extension) &&
                    extension.TryGetValue(out IEncodeable? encodeable))
                {
                    // do conversion.
                    value = Encode(context, encodeable!, useXml);
                    return ServiceResult.Good;
                }

                return StatusCodes.BadDataEncodingUnsupported;
            }
            catch (Exception e)
            {
                return ServiceResult.Create(
                    e,
                    StatusCodes.BadTypeMismatch,
                    "Could not convert value to requested format.");
            }
        }

        /// <summary>
        /// Encodes the object in XML or Binary
        /// </summary>
        public static ExtensionObject Encode(
            IServiceMessageContext context,
            IEncodeable encodeable,
            bool useXml)
        {
            if (useXml)
            {
                XmlElement body = EncodeXml(encodeable, context);
                return new ExtensionObject(encodeable.XmlEncodingId, body);
            }
            else
            {
                ByteString body = EncodeBinary(encodeable, context);
                return new ExtensionObject(encodeable.BinaryEncodingId, body);
            }
        }

        /// <summary>
        /// Encodes the object in XML.
        /// </summary>
        public static XmlElement EncodeXml(IEncodeable encodeable, IServiceMessageContext context)
        {
            // create encoder.
            using var encoder = new XmlEncoder(context);
            // write body.
            encoder.WriteExtensionObjectBody(new ExtensionObject(encodeable));
            // return as xml element
            return XmlElement.From(encoder.CloseAndReturnText());
        }

        /// <summary>
        /// Encodes the object in binary
        /// </summary>
        public static ByteString EncodeBinary(IEncodeable encodeable, IServiceMessageContext context)
        {
            using var encoder = new BinaryEncoder(context);
            // Wrute body
            encoder.WriteEncodeable(null, encodeable, encodeable.TypeId);
            // Return as byte string
            return ByteString.From(encoder.CloseAndReturnBuffer());
        }

        /// <inheritdoc/>
        public virtual object Clone()
        {
            return MemberwiseClone();
        }

        /// <summary>
        /// Returns a deep copy of an encodeable object.
        /// </summary>
        public new object MemberwiseClone()
        {
            return base.MemberwiseClone();
        }
    }
}
